DECLARE
    V_REQUEST_ID   RAW(16);
    V_TERMINAL_ID  RAW(16);
    V_SAVED_ID     RAW(16);
    V_JSON         CLOB;
BEGIN

    /* ============================================================
       Request ID

       ADD TERMINAL flow:
       Use the NEW request created by Continue.

       Do NOT use:
           appsmith.URL.queryParams.requestId

       because that is the original/source request.
       ============================================================ */

    V_REQUEST_ID :=
        HEXTORAW(
            REPLACE(
                '{{ JS_ADD_TERMINAL.getRequestId() }}',
                '-',
                ''
            )
        );


    /* ============================================================
       Terminal ID

       ADD  -> NULL
       EDIT -> stored terminal ID
       ============================================================ */

    V_TERMINAL_ID :=
        CASE
            WHEN '{{ appsmith.store.MMS_TERMINAL_EDIT_ID }}' IS NULL
                 OR TRIM('{{ appsmith.store.MMS_TERMINAL_EDIT_ID }}') = ''
            THEN NULL

            ELSE HEXTORAW(
                REPLACE(
                    '{{ appsmith.store.MMS_TERMINAL_EDIT_ID }}',
                    '-',
                    ''
                )
            )
        END;


    /* ============================================================
       Terminal data
       ============================================================ */

    V_JSON :=
        '{{ JSON.stringify(
            JS_GRID_TERMINAL.getTerminalData()
        ) }}';


    /* ============================================================
       Save Terminal
       ============================================================ */

    TALY_BO_REP.MMS_TERMINAL_PKG.SAVE_TERMINAL(
        P_REQUEST_ID    => V_REQUEST_ID,
        P_TERMINAL_ID   => V_TERMINAL_ID,
        P_TERMINAL_JSON => V_JSON,
        P_SAVED_ID      => V_SAVED_ID
    );

END;
